(function () { 'use strict'; try { var pendingKey = 'shopvivaliz_pending_coupon'; var usedKey = 'shopvivaliz_first_coupon_used'; var pending = String(localStorage.getItem(pendingKey) || '').toUpperCase(); var used = String(localStorage.getItem(usedKey) || '').toUpperCase(); var params = new URLSearchParams(window.location.search || ''); var deeplinkCoupon = String(params.get('cupom') || '').trim().toUpperCase(); if (deeplinkCoupon && /^[A-Z0-9_-]{2,30}$/.test(deeplinkCoupon)) { localStorage.setItem(pendingKey, deeplinkCoupon); pending = deeplinkCoupon; } if (pending === 'PRIMEIRA10' || pending === 'PRIMEIRA15') { localStorage.removeItem(pendingKey); } if (used === 'PRIMEIRA10' || used === 'PRIMEIRA15') { localStorage.removeItem(usedKey); } } catch (error) {} })();